    --df-input-node-border: rgba(251, 146, 60, 0.25);
    --df-input-node-accent: #fb923c;
    --df-output-node-bg: rgba(185, 28, 28, 0.35);
    --df-output-node-bg-hover: rgba(185, 28, 28, 0.5);
    --df-output-node-border: rgba(248, 113, 113, 0.25);
    --df-output-node-accent: #f87171;
    --df-default-node-accent: #fb923c;
    --df-edge-stroke: #fdba74;
    --df-edge-stroke-selected: #fb923c;
    --df-edge-stroke-animated: #fcd34d;
    --df-handle-bg-connected: #fb923c;
    --df-handle-bg-valid: #fdba74;
    --df-background-color: #27150a;
    --df-background-pattern: #431407;
}

/* Midnight - Deep Blues and Purples */
.df-scheme-midnight,
.df-scheme-midnight .react-flow {
    --df-input-node-bg: rgba(224, 231, 255, 0.65);
    --df-input-node-bg-hover: rgba(224, 231, 255, 0.8);
