    --df-output-node-bg-hover: rgba(243, 232, 255, 0.8);
    --df-output-node-border: rgba(168, 85, 247, 0.3);
    --df-output-node-accent: #a855f7;
    --df-default-node-accent: #818cf8;
    --df-edge-stroke: #6366f1;
    --df-edge-stroke-selected: #818cf8;
    --df-edge-stroke-animated: #a78bfa;
    --df-handle-bg-connected: #818cf8;
    --df-handle-bg-valid: #a78bfa;
    --df-selection-bg: rgba(99, 102, 241, 0.08);
    --df-selection-border: rgba(99, 102, 241, 0.4);
    --df-minimap-mask: rgba(99, 102, 241, 0.15);
    --df-background-color: #eef2ff;
    --df-background-pattern: #c7d2fe;
}

[data-mantine-color-scheme="dark"] .df-scheme-midnight,
[data-mantine-color-scheme="dark"] .df-scheme-midnight .react-flow,
.df-scheme-midnight .react-flow.dark {
    --df-input-node-bg: rgba(67, 56, 202, 0.35);
    --df-input-node-bg-hover: rgba(67, 56, 202, 0.5);
    --df-input-node-border: rgba(129, 140, 248, 0.25);
    --df-input-node-accent: #818cf8;
    --df-output-node-bg: rgba(126, 34, 206, 0.35);
    --df-output-node-bg-hover: rgba(126, 34, 206, 0.5);
    --df-output-node-border: rgba(192, 132, 252, 0.25);
    --df-output-node-accent: #c084fc;
    --df-default-node-accent: #a5b4fc;
    --df-edge-stroke: #a5b4fc;
    --df-edge-stroke-selected: #818cf8;
    --df-edge-stroke-animated: #c4b5fd;
    --df-handle-bg-connected: #818cf8;
    --df-handle-bg-valid: #a78bfa;
    --df-background-color: #0f0a29;
