}

/* Rose - Pinks and Reds */
.df-scheme-rose,
.df-scheme-rose .react-flow {
    --df-input-node-bg: rgba(255, 228, 230, 0.65);
    --df-input-node-bg-hover: rgba(255, 228, 230, 0.8);
    --df-input-node-border: rgba(244, 63, 94, 0.3);
    --df-input-node-accent: #f43f5e;
    --df-output-node-bg: rgba(252, 231, 243, 0.65);
    --df-output-node-bg-hover: rgba(252, 231, 243, 0.8);
    --df-output-node-border: rgba(236, 72, 153, 0.3);
    --df-output-node-accent: #ec4899;
    --df-default-node-accent: #fb7185;
    --df-edge-stroke: #e11d48;
    --df-edge-stroke-selected: #f43f5e;
    --df-edge-stroke-animated: #fb7185;
    --df-handle-bg-connected: #f43f5e;
    --df-handle-bg-valid: #fb7185;
    --df-selection-bg: rgba(244, 63, 94, 0.08);
    --df-selection-border: rgba(244, 63, 94, 0.4);
