 - Theme presets (glass, solid, minimal)\n * - Color schemes (default, ocean, forest, sunset, midnight, rose)\n *\n * Compatible with dash-mantine-components and React Flow 12+\n */\n\n/* =============================================================================\n   SECTION 1: CSS CUSTOM PROPERTIES (Theme Variables)\n   ============================================================================= */\n\n:root {\n    /* ------------------------------------------------------------------\n       Glass Effect Properties\n       ------------------------------------------------------------------ */\n    --df-glass-blur: 12px;\n    --df-glass-blur-light: 8px;\n    --df-glass-blur-heavy: 20px;\n    --df-glass-saturate: 180%;\n\n    /* ------------------------------------------------------------------\n       Theme Colors - Light Mode (Default)\n       ------------------------------------------------------------------ */\n\n    /* Base glass appearance */\n    --df-glass-bg: rgba(255, 255, 255, 0.72);\n    --df-glass-bg-hover: rgba(255, 255, 255, 0.85);\n    --df-glass-border: rgba(255, 255, 255, 0.5);\n    --df-glass-shadow: 0 8px 32px rgba(31, 38, 135, 0.15);\n    --df-glass-shadow-hover: 0 8px 32px rgba(31, 38, 135, 0.25);\n    --df-glass-inset: inset 0 1px 0 0 rgba(255, 255, 255, 0.6);\n    --df-glass-inset-bottom: inset 0 -1px 0 0 rgba(0, 0, 0, 0.02);\n\n    /* Node base colors */\n    --df-node-bg: var(--df-glass-bg);\n    --df-node-bg-hover: var(--df-glass-bg-hover);\n    --df-node-border: var(--df-glass-border);\n    --df-node-text: #1a1b1e;\n    --df-node-text-secondary: #495057;\n    --df-node-shadow: var(--df-glass-shadow);\n\n    /* Input node - Green tint */\n    --df-input-node-bg: rgba(209, 250, 229, 0.65);\n    --df-input-node-bg-hover: rgba(209, 250, 229, 0.8);\n    --df-input-node-border: rgba(16, 185, 129, 0.3);\n    --df-input-node-accent: #10b981;\n\n    /* Output node - Purple tint */\n    --df-output-node-bg: rgba(237, 233, 254, 0.65);\n    --df-output-node-bg-hover: rgba(237, 233, 254, 0.8);\n    --df-output-node-border: rgba(139, 92, 246, 0.3);\n    --df-output-node-accent: #8b5cf6;\n\n    /* Default node - Neutral */\n    --df-default-node-bg: var(--df-glass-bg);\n    --df-default-node-border: var(--df-glass-border);\n    --df-default-node-accent: #3b82f6;\n\n    /* Group node */\n    --df-group-node-bg: rgba(243, 244, 246, 0.5);\n    --df-group-node-border: rgba(156, 163, 175, 0.4);\n\n    /* Toolbar & panels */\n    --df-toolbar-bg: rgba(255, 255, 255, 0.95);\n    --df-toolbar-border: rgba(0, 0, 0, 0.1);\n    --df-toolbar-shadow: 0 4px 12px rgba(0, 0, 0, 0.1);\n\n    /* Edge colors */\n    --df-edge-stroke: #64748b;\n    --df-edge-stroke-width: 2;\n    --df-edge-stroke-selected: #3b82f6;\n    --df-edge-stroke-animated: #8b5cf6;\n\n    /* Edge label */\n    --df-edge-label-bg: rgba(255, 255, 255, 0.85);\n    --df-edge-label-border: rgba(255, 255, 255, 0.6);\n    --df-edge-label-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);\n\n    /* Handle colors */\n    --df-handle-bg: #fff;\n    --df-handle-border: #64748b;\n    --df-handle-bg-connected: #3b82f6;\n    --df-handle-bg-valid: #10b981;\n    --df-handle-size: 14px;\n    --df-handle-size-hover: 18px;\n\n    /* Background */\n    --df-background-color: #fafafa;\n    --df-background-pattern: #e5e7eb;\n\n    /* Controls & MiniMap */\n    --df-controls-bg: var(--df-glass-bg);\n    --df-controls-border: var(--df-glass-border);\n    --df-minimap-bg: rgba(255, 255, 255, 0.85);\n    --df-minimap-mask: rgba(59, 130, 246, 0.15);\n    --df-minimap-node-fill: #64748b;\n    --df-minimap-node-stroke: #475569;\n\n    /* Selection */\n    --df-selection-bg: rgba(59, 130, 246, 0.08);\n    --df-selection-border: rgba(59, 130, 246, 0.4);\n    --df-selection-ring: 0 0 0 2px var(--df-selection-border);\n\n    /* Connection line */\n    --df-connection-line-stroke: var(--df-edge-stroke-selected);\n    --df-connection-line-width: 2;\n\n    /* ------------------------------------------------------------------\n       Spacing & Sizing\n       ------------------------------------------------------------------ */\n    --df-spacing-xs: 4px;\n    --df-spacing-sm: 8px;\n    --df-spacing-md: 12px;\n    --df-spacing-lg: 16px;\n    --df-spacing-xl: 24px;\n\n    /* Border radius */\n    --df-radius-xs: 4px;\n    --df-radius-sm: 6px;\n    --df-radius-md: 10px;\n    --df-radius-lg: 14px;\n    --df-radius-xl: 20px;\n\n    /* Transitions */\n    --df-transition-fast: 150ms cubic-bezier(0.4, 0, 0.2, 1);\n    --df-transition-normal: 250ms cubic-bezier(0.4, 0, 0.2, 1);\n    --df-transition-slow: 350ms cubic-bezier(0.4, 0, 0.2, 1);\n\n    /* Node sizing */\n    --df-node-min-width: 150px;\n    --df-node-default-width: clamp(160px, 18vw, 300px);\n    --df-group-node-min-width: clamp(220px, 22vw, 400px);\n    --df-group-node-min-height: clamp(180px, 25vh, 400px);\n\n    /* ------------------------------------------------------------------\n       Map to React Flow CSS Variables\n       ------------------------------------------------------------------ */\n    --xy-edge-stroke-default: var(--df-edge-stroke);\n    --xy-edge-stroke-width-default: var(--df-edge-stroke-width);\n    --xy-edge-stroke-selected-default: var(--df-edge-stroke-selected);\n    --xy-connectionline-stroke-default: var(--df-connection-line-stroke);\n    --xy-connectionline-stroke-width-default: var(--df-connection-line-width);\n    --xy-node-background-color-default: var(--df-node-bg);\n    --xy-node-border-default: 1px solid var(--df-node-border);\n    --xy-node-color-default: var(--df-node-text);\n    --xy-handle-background-color-default: var(--df-handle-bg);\n    --xy-handle-border-color-default: var(--df-handle-border);\n    --xy-background-pattern-dots-color-default: var(--df-background-pattern);\n    --xy-background-pattern-line-color-default: var(--df-background-pattern);\n    --xy-background-pattern-cross-color-default: var(--df-background-pattern);\n    --xy-minimap-background-color-default: var(--df-minimap-bg);\n    --xy-selection-background-color-default: var(--df-selection-bg);\n    --xy-selection-border-default: 1px dotted var(--df-selection-border);\n    --xy-controls-button-background-color-default: var(--df-controls-bg);\n    --xy-controls-button-border-color-default: var(--df-controls-border);\n}\n\n/* =============================================================================\n   SECTION 2: DARK MODE VARIABLES\n\n   Supports multiple dark mode detection methods:\n   - React Flow colorMode=\"dark\" adds .dark class\n   - Mantine uses data-mantine-color-scheme=\"dark\"\n   - Custom data-theme=\"dark\" attribute\n   ============================================================================= */\n\n/* React Flow dark mode */\n.react-flow.dark,\n/* Mantine dark mode */\n:root[data-mantine-color-scheme=\"dark\"],\n[data-mantine-color-scheme=\"dark\"],\n/* Custom dark mode class */\n.dark-mode,\n[data-theme=\"dark\"] {\n    /* Glass effect - Dark mode */\n    --df-glass-bg: rgba(26, 27, 30, 0.72);\n    --df-glass-bg-hover: rgba(37, 38, 43, 0.85);\n    --df-glass-border: rgba(255, 255, 255, 0.08);\n    --df-glass-shadow: 0 8px 32px rgba(0, 0, 0, 0.35);\n    --df-glass-shadow-hover: 0 8px 32px rgba(0, 0, 0, 0.5);\n    --df-glass-inset: inset 0 1px 0 0 rgba(255, 255, 255, 0.05);\n    --df-glass-inset-bottom: inset 0 -1px 0 0 rgba(0, 0, 0, 0.1);\n\n    /* Node colors - Dark mode */\n    --df-node-bg: var(--df-glass-bg);\n    --df-node-bg-hover: var(--df-glass-bg-hover);\n    --df-node-border: var(--df-glass-border);\n    --df-node-text: #f1f3f5;\n    --df-node-text-secondary: #909296;\n    --df-node-shadow: var(--df-glass-shadow);\n\n    /* Input node - Green tint dark */\n    --df-input-node-bg: rgba(6, 78, 59, 0.45);\n    --df-input-node-bg-hover: rgba(6, 78, 59, 0.6);\n    --df-input-node-border: rgba(16, 185, 129, 0.25);\n    --df-input-node-accent: #34d399;\n\n    /* Output node - Purple tint dark */\n    --df-output-node-bg: rgba(76, 29, 149, 0.35)