gn: left;\n}\n\n.df-glass-node.df-layout-horizontal .df-node-text-column .df-node-label {\n    text-align: left;\n}\n\n.df-glass-node.df-layout-horizontal .df-node-text-column .df-node-sublabel {\n    text-align: left;\n}\n\n.df-glass-node.df-layout-horizontal .df-node-text-column .df-node-body {\n    text-align: left;\n    margin-top: var(--df-spacing-xs);\n}\n\n/* Horizontal layout with accent bars */\n.df-glass-node.df-input-node.df-layout-horizontal {\n    padding-top: calc(var(--df-spacing-sm) + 4px);\n}\n\n.df-glass-node.df-output-node.df-layout-horizontal {\n    padding-bottom: calc(var(--df-spacing-sm) + 4px);\n}\n\n/* =============================================================================\n   SECTION 6: SPECIFIC NODE TYPES\n   ============================================================================= */\n\n/* Input Node */\n.df-glass-node.df-input-node {\n    background: var(--df-input-node-bg);\n    border-color: var(--df-input-node-border);\n    padding-top: calc(var(--df-spacing-md) + 4px);\n}\n\n.df-glass-node.df-input-node:hover {\n    background: var(--df-input-node-bg-hover);\n}\n\n.df-glass-node.df-input-node .df-node-accent-bar {\n    position: absolute;\n    top: 0;\n    left: 0;\n    right: 0;\n    height: 3px;\n    background: var(--df-input-node-accent);\n    border-radius: var(--df-radius-lg) var(--df-radius-lg) 0 0;\n}\n\n.df-glass-node.df-input-node .df-node-icon {\n    background: var(--df-input-node-accent);\n}\n\n/* Output Node */\n.df-glass-node.df-output-node {\n    background: var(--df-output-node-bg);\n    border-color: var(--df-output-node-border);\n    padding-bottom: calc(var(--df-spacing-md) + 4px);\n}\n\n.df-glass-node.df-output-node:hover {\n    background: var(--df-output-node-bg-hover);\n}\n\n.df-glass-node.df-output-node .df-node-accent-bar {\n    position: absolute;\n    bottom: 0;\n    left: 0;\n    right: 0;\n    height: 3px;\n    background: var(--df-output-node-accent);\n    border-radius: 0 0 var(--df-radius-lg